import{_ as e,o as a,c as s,aj as o}from"./framework.js";const m=JSON.parse('{"title":"Settings | Settings | Admin CMS","description":"Settings configures site basics, domains, third-party integrations, admin users and permissions, Hooks, Cookie, and more. Shares /system prefix with Operations Center but different left…","frontmatter":{"title":"Settings | Settings | Admin CMS","description":"Settings configures site basics, domains, third-party integrations, admin users and permissions, Hooks, Cookie, and more. Shares /system prefix with Operations Center but different left…","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/cms/settings/index.html"}]]},"headers":[],"relativePath":"cms/settings/index.md","filePath":"en/cms/settings/index.md","lastUpdated":1781010536000}'),d={name:"cms/settings/index.md"};function n(r,t,i,c,l,h){return a(),s("div",null,[...t[0]||(t[0]=[o('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><blockquote><p>Menu: left sidebar <strong>Settings</strong> group (enable in <strong>Edit Menu</strong>) Route prefix: <code>/_Admin/system/...?SiteId={siteGuid}</code></p></blockquote><p><strong>Settings</strong> configures site basics, domains, third-party <strong>integrations</strong>, admin users and permissions, Hooks, Cookie, and more. Shares <code>/system</code> prefix with <a href="./../operations/">Operations Center</a> but <strong>different left menu group</strong> (<code>menu.name</code> is <code>system</code>, label “Settings”).</p><div class="info custom-block"><p class="custom-block-title">Advanced menu</p><p>The entire <strong>Settings</strong> group is <code>advanced: true</code> on routes—hidden by default; enable in <a href="./../navigation.html#permissions-and-edit-menu">Edit Menu</a>. <strong>Roles</strong>, <strong>Request Hooks</strong>, <strong>Action Hooks</strong>, and <strong>AI Service</strong> sub-items are also <code>advanced</code>.</p></div><div class="tip custom-block"><p class="custom-block-title">Overlap with Operations Center</p><table tabindex="0"><thead><tr><th>Menu</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td><strong>AI Service</strong></td><td><code>/system/ai-service</code></td><td><strong>Same page</strong> as Operations Center entry; single doc at <a href="./ai-service.html">AI Service</a> with cross-links</td></tr></tbody></table><p>Other Operations menus (visitor logs, sync, etc.): <a href="./../operations/">Operations Center</a>.</p></div><h2 id="how-to-open" tabindex="-1">How to Open <a class="header-anchor" href="#how-to-open" aria-label="Permalink to &quot;How to Open&quot;">​</a></h2><ol><li>In <a href="./../navigation.html#permissions-and-edit-menu">Edit Menu</a>, enable <strong>Settings</strong> and needed sub-items.</li><li>Expand <strong>Settings</strong> in the left sidebar.</li></ol><h2 id="submenus-admin-order" tabindex="-1">Submenus (admin order) <a class="header-anchor" href="#submenus-admin-order" aria-label="Permalink to &quot;Submenus (admin order)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Menu</th><th>Path</th><th>Permission (feature)</th><th>Doc</th><th>Status</th></tr></thead><tbody><tr><td>Basic Settings</td><td><code>/system/settings</code></td><td><code>site·edit</code></td><td><a href="./basic/">Basic Settings</a></td><td>✅</td></tr><tr><td>Domains</td><td><code>/system/domains</code></td><td><code>domain</code></td><td><a href="./domains.html">Domains</a></td><td>✅</td></tr><tr><td>Integrations</td><td><code>/system/config</code></td><td><code>config</code></td><td><a href="./integrations/">Integrations</a></td><td>✅</td></tr><tr><td>Site Users</td><td><code>/system/siteuser</code></td><td><code>siteUser</code></td><td><a href="./site-users.html">Site Users</a></td><td>✅</td></tr><tr><td>Roles</td><td><code>/system/roles</code></td><td><code>role</code></td><td><a href="./roles.html">Roles</a></td><td>✅</td></tr><tr><td>Request Hooks</td><td><code>/system/front-events</code></td><td><code>frontEvents</code></td><td><a href="./request-hooks.html">Request Hooks</a></td><td>✅</td></tr><tr><td>Action Hooks</td><td><code>/system/backend-events</code></td><td><code>backendEvents</code></td><td><a href="./action-hooks.html">Action Hooks</a></td><td>✅</td></tr><tr><td>Cookie Management</td><td><code>/system/cookie</code></td><td><code>site·edit</code></td><td><a href="./cookie.html">Cookie</a></td><td>✅</td></tr><tr><td>AI Service</td><td><code>/system/ai-service</code></td><td><code>ai</code></td><td><a href="./ai-service.html">AI Service</a></td><td>✅</td></tr></tbody></table><p>Deep link examples:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/_Admin/system/settings?SiteId={siteGuid}&amp;name=basic</span></span>\n<span class="line"><span>/_Admin/system/config?SiteId={siteGuid}&amp;group=Database</span></span>\n<span class="line"><span>/_Admin/system/front-events/edit?SiteId={siteGuid}&amp;name=RouteFinding&amp;display=RouteFinding</span></span>\n<span class="line"><span>/_Admin/system/backend-events/edit?SiteId={siteGuid}&amp;name=ContentUpdated&amp;display=ContentUpdated</span></span></code></pre></div><h2 id="sub-routes-without-sidebar-menu" tabindex="-1">Sub-routes Without Sidebar Menu <a class="header-anchor" href="#sub-routes-without-sidebar-menu" aria-label="Permalink to &quot;Sub-routes Without Sidebar Menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Route</th><th>Entered from</th><th>Documented in</th></tr></thead><tbody><tr><td><code>/system/settings?name={tab}</code></td><td>Basic Settings tab switch</td><td><a href="./basic/">Basic Settings</a> tab docs</td></tr><tr><td><code>/system/front-events/edit</code></td><td>Request Hooks list</td><td><a href="./request-hooks.html">Request Hooks</a></td></tr><tr><td><code>/system/backend-events/edit</code></td><td>Action Hooks list</td><td><a href="./action-hooks.html">Action Hooks</a></td></tr></tbody></table><h3 id="basic-settings-tabs-name-query" tabindex="-1">Basic Settings Tabs (<code>name</code> query) <a class="header-anchor" href="#basic-settings-tabs-name-query" aria-label="Permalink to &quot;Basic Settings Tabs (`name` query)&quot;">​</a></h3><table tabindex="0"><thead><tr><th><code>name</code></th><th>Tab label</th><th>Main topics</th></tr></thead><tbody><tr><td><code>basic</code></td><td>General</td><td>Display name, Base URL, Force SSL, SPA, <strong>multilingual</strong>, import/export package</td></tr><tr><td><code>access</code></td><td>Access Control</td><td>IP / region restrictions, etc.</td></tr><tr><td><code>performance</code></td><td>Performance</td><td>Cache, compression, etc.</td></tr><tr><td><code>seo</code></td><td>SEO</td><td>Site-level SEO switches</td></tr><tr><td><code>editor</code></td><td>Editor</td><td>Admin editor preferences</td></tr><tr><td><code>advance</code></td><td>Advanced</td><td>Default database, SQL log, constraint fix, etc. (ties to <a href="./../database/sql-logs.html">SQL logs</a>)</td></tr></tbody></table><p>Multilingual lives in the <strong>General</strong> tab <code>Multilingual</code> section—not a separate menu; see <a href="./basic/general.html#multilingual">Basic · General Tab</a>. Do not confuse with <a href="./../development/spa-multilingual.html">Development -&gt; SPA multilingual</a>.</p><h2 id="integrations-config-preview" tabindex="-1">Integrations (<code>config</code>) Preview <a class="header-anchor" href="#integrations-config-preview" aria-label="Permalink to &quot;Integrations (`config`) Preview&quot;">​</a></h2><p><strong>Integrations</strong> page folds <strong>Group</strong> sections for <code>CoreSetting</code> items; see <a href="./integrations/">Integrations</a>.</p><table tabindex="0"><thead><tr><th>Group</th><th>Doc</th></tr></thead><tbody><tr><td><strong>Database</strong></td><td><a href="./integrations/database.html">Database</a></td></tr><tr><td><strong>Payment</strong></td><td><a href="./integrations/payment.html">Payment</a></td></tr><tr><td><strong>SMS</strong></td><td><a href="./integrations/sms.html">SMS</a></td></tr><tr><td><strong>OAuth2</strong></td><td><a href="./integrations/oauth2.html">OAuth2</a></td></tr><tr><td><strong>Storage</strong></td><td><a href="./integrations/storage.html">Storage</a></td></tr><tr><td><strong>Others</strong></td><td><a href="./integrations/others.html">Others</a></td></tr></tbody></table><p>Payment integrations are <strong>not</strong> duplicated in Commerce settings—use <strong>Payment</strong> group here.</p><h2 id="suggested-configuration-order" tabindex="-1">Suggested Configuration Order <a class="header-anchor" href="#suggested-configuration-order" aria-label="Permalink to &quot;Suggested Configuration Order&quot;">​</a></h2><p>Typical implementation path:</p><ol><li><strong><a href="./basic/">Basic Settings</a></strong> — six tab docs (multilingual, SQL log switch, etc.)</li><li><strong><a href="./domains.html">Domains</a></strong> — bindings, primary domain, SSL</li><li><strong><a href="./integrations/">Integrations</a></strong> — group docs; Database / Payment cross-link to API</li><li><strong><a href="./site-users.html">Site Users</a></strong> · <strong><a href="./roles.html">Roles</a></strong> — admin accounts and feature permissions</li><li><strong><a href="./request-hooks.html">Request Hooks</a></strong> · <strong><a href="./action-hooks.html">Action Hooks</a></strong> — including edit sub-pages</li><li><strong><a href="./cookie.html">Cookie</a></strong></li><li><strong><a href="./ai-service.html">AI Service</a></strong> — cross-link <a href="./../operations/">Operations Center</a></li></ol><h2 id="development-reference-kscript-api" tabindex="-1">Development Reference (KScript / API) <a class="header-anchor" href="#development-reference-kscript-api" aria-label="Permalink to &quot;Development Reference (KScript / API)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Admin capability</th><th>API doc</th></tr></thead><tbody><tr><td>Integrations CoreSetting</td><td><code>k.config</code> / site settings APIs (per item)</td></tr><tr><td>Payment</td><td><a href="/kb-docs/api/payment/">k.payment</a></td></tr><tr><td>Database connections</td><td><a href="/kb-docs/api/database/">k.DB</a></td></tr><tr><td>Multilingual / Label</td><td><a href="/kb-docs/api/label/">k.label</a></td></tr><tr><td>JWT, etc.</td><td>APIs for each integration</td></tr></tbody></table><p>CMS docs cover <strong>admin click paths</strong> and form fields; script signatures and examples stay in API docs.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Doc</th><th>Description</th></tr></thead><tbody><tr><td><a href="./../navigation.html">Site admin menu overview</a></td><td>Full menu tree</td></tr><tr><td><a href="./../database/">Database</a></td><td>Table management after Database integration</td></tr><tr><td><a href="./../operations/">Operations Center</a></td><td>Observation and collaboration under <code>/system</code></td></tr></tbody></table>',28)])])}const u=e(d,[["render",n]]);export{m as __pageData,u as default};
